On 7/9/26 10:45 PM, Hyeoncheol Jeong wrote:
> struct utp_transfer_cmd_desc {
>           u8 command_upiu[ALIGNED_UPIU_SIZE];
> -        u8 response_upiu[ALIGNED_UPIU_SIZE];
> +        u8 response_upiu[ALIGNED_RSP_UPIU_SIZE];
>           u8 prd_table[];
